import { mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join } from 'node:path'
import { deflateRawSync } from 'node:zlib'
import { fixture } from '@test/fixtures'
import { strFromU8, strToU8, unzipSync, zipSync } from 'fflate'
import { describe, expect, it } from 'vitest'
import { buildNcepFromNc } from './fromNc'
import { type NcepIssue, type NcepPackage, ncepErrors, parseNcepPackage } from './ncepParse'
import { crc32 } from './ncex'
import { type RawZipEntry, readZipRaw, writeZipRaw } from './probeZip'

/**
 * Own NC → NCEP structure probes. Each package is generated by the current converter, then one
 * structural variable is changed. The pack isolates the strongest current suspect: the missing
 * Adobe `USERPATH` group on U/I packages.
 *
 *   WRITE_NCEX_PROBES=~/Downloads/ncep-probes-own-structure \
 *     pnpm exec vitest run src/lib/wisecam/probes.ownStructure.test.ts
 */
const outDir = process.env.WRITE_NCEX_PROBES

type Files = Record<string, Uint8Array>
type Edit = (text: string) => string

interface ProbeReport {
  file: string
  mark: string
  family: string
  variant: string
  errors: string[]
  warnings: string[]
  sectionPaths: number
  userPaths: number
}

const SECTIONS = [
  { mark: 'M-1', family: 'PFC380' },
  { mark: 'M-3', family: 'UB310' },
  { mark: 'M-34', family: 'PFC300' },
  { mark: 'M-35', family: 'SHS89' },
  { mark: 'M-42', family: 'RHS100x50' },
] as const

const CODES = {
  'M-1': { control: 700, userPath: 701, realAdobe: 702, realPart: 703, realBoth: 704, nested: 705 },
  'M-3': { control: 706, userPath: 707, realAdobe: 708 },
  'M-34': { control: 709, userPath: 710 },
  'M-35': { control: 711 },
  'M-42': { control: 712 },
} as const

function svgName(files: Files, kind: 'Adobe' | 'Part'): string {
  const root = strFromU8(files['CAD/CadRoot.xml'] as Uint8Array)
  const tag = root.match(new RegExp(`<${kind}\\b[^>]*/>`))?.[0] ?? ''
  return /svgname="([^"]+)"/.exec(tag)?.[1] ?? ''
}

function svgText(files: Files, kind: 'Adobe' | 'Part'): string {
  return strFromU8(files[`CAD/${svgName(files, kind)}`] as Uint8Array)
}

function own(mark: string, uniqueMark: string): { entries: RawZipEntry[]; files: Files } {
  const bytes = buildNcepFromNc(readFileSync(fixture('ncep', `${mark}.nc1`), 'utf8'), {
    mark: uniqueMark,
  })
  if (!bytes) throw new Error(`cannot build own ${mark}`)
  return { entries: readZipRaw(bytes), files: unzipSync(bytes) as Files }
}

function real(mark: string): Files {
  return unzipSync(new Uint8Array(readFileSync(fixture('ncep', `${mark}.ncep`)))) as Files
}

function rename(text: string, from: string, to: string): string {
  return text
    .split(`Name=${from}`)
    .join(`Name=${to}`)
    .split(`Part=${from}`)
    .join(`Part=${to}`)
    .split(`LabelContent=${from}`)
    .join(`LabelContent=${to}`)
    .split(`>${from}</text>`)
    .join(`>${to}</text>`)
}

function partId(files: Files): string {
  const root = strFromU8(files['CAD/CadRoot.xml'] as Uint8Array)
  return /<Part\b[^>]*idref="([^"]+)"/.exec(root)?.[1] ?? ''
}

function setPartRef(svg: string, id: string): string {
  return svg.replace(/wh:refid="[^"]*"/, `wh:refid="${id}"`)
}

function userPathGroup(adobe: string): string {
  const group = adobe.match(/<g\b[^>]*wh:params="USERPATH=USERPATH;"[^>]*>[\s\S]*?<\/g>/)?.[0]
  if (!group) throw new Error('real adobe has no USERPATH group')
  return group
}

function removeUserPath(adobe: string): string {
  return adobe.replace(/<g\b[^>]*wh:params="USERPATH=USERPATH;"[^>]*>[\s\S]*?<\/g>/, '')
}

function insertBeforeSection(adobe: string, group: string): string {
  const at = adobe.lastIndexOf('<g ')
  if (at < 0) throw new Error('adobe has no section group')
  return `${adobe.slice(0, at)}${group}\n ${adobe.slice(at)}`
}

function nestSection(svg: string): string {
  const part = svg.match(/<g\b[^>]*wh:class="cadpart"[^>]*>[\s\S]*?<\/g>/)?.[0] ?? ''
  const section = svg.match(/<g\b[^>]*wh:class="cadgroup"[^>]*>[\s\S]*?<\/g>/)?.[0] ?? ''
  if (!part || !section) throw new Error('part/adobe section structure not found')
  const nested = part.replace(/<\/g>$/, `${section}</g>`)
  return svg.replace(section, '').replace(part, nested)
}

function writeProbe(
  out: string,
  name: string,
  entries: RawZipEntry[],
  files: Files,
  edits: Record<string, Edit>,
): NcepPackage {
  const raw = entries.map((entry) => {
    const edit = edits[entry.name]
    if (!edit) return entry
    const data = strToU8(edit(strFromU8(files[entry.name] as Uint8Array)))
    const compressed = new Uint8Array(deflateRawSync(data))
    return {
      ...entry,
      compressed,
      compressedSize: compressed.length,
      uncompressedSize: data.length,
      crc: crc32(data),
    }
  })
  const bytes = writeZipRaw(raw)
  writeFileSync(join(out, name), bytes)
  return parseNcepPackage(bytes)
}

function codesFor(issues: NcepIssue[], severity: 'error' | 'warning'): string[] {
  return issues.filter((issue) => issue.severity === severity).map((issue) => issue.code)
}

function report(
  file: string,
  mark: string,
  family: string,
  variant: string,
  pkg: NcepPackage,
): ProbeReport {
  return {
    file,
    mark,
    family,
    variant,
    errors: codesFor(pkg.issues, 'error'),
    warnings: codesFor(pkg.issues, 'warning'),
    sectionPaths:
      pkg.partSvg?.sections.reduce((total, group) => total + group.wires.length, 0) ?? 0,
    userPaths: pkg.adobeSvg?.userPaths.length ?? 0,
  }
}

function lineFor(entry: ProbeReport): string {
  const issues = [
    ...entry.errors.map((code) => `error:${code}`),
    ...entry.warnings.map((code) => `warn:${code}`),
  ]
  return `| ${entry.file} | ${entry.mark} | ${entry.family} | ${entry.variant} | ${entry.sectionPaths} | ${entry.userPaths} | ${issues.join(', ') || 'ok'} |`
}

describe.skipIf(!outDir)('write own NC structure probes', () => {
  it('writes 700-712 and the transfer ZIP', () => {
    const out = outDir as string
    mkdirSync(out, { recursive: true })
    const reports: ProbeReport[] = []

    for (const section of SECTIONS) {
      const codes = CODES[section.mark] as Record<string, number>
      const realFiles = real(section.mark)
      const realAdobe = svgText(realFiles, 'Adobe')
      const realPart = svgText(realFiles, 'Part')

      const controlMark = `${section.mark}-${codes.control}`
      const control = own(section.mark, controlMark)
      const controlName = `${codes.control}-${section.mark}-control.ncep`
      const controlPkg = writeProbe(out, controlName, control.entries, control.files, {})
      reports.push(report(controlName, controlMark, section.family, 'control', controlPkg))

      const adobeName = svgName(control.files, 'Adobe')
      const partName = svgName(control.files, 'Part')

      if ('userPath' in codes) {
        const mark = `${section.mark}-${codes.userPath}`
        const base = own(section.mark, mark)
        const name = `${codes.userPath}-${section.mark}-userpath.ncep`
        const pkg = writeProbe(out, name, base.entries, base.files, {
          [`CAD/${adobeName}`]: (text) =>
            insertBeforeSection(removeUserPath(text), userPathGroup(realAdobe)),
        })
        reports.push(
          report(name, mark, section.family, 'our Adobe without USERPATH + real USERPATH', pkg),
        )
        expect(codesFor(pkg.issues, 'warning')).not.toContain('adobe-userpath')
      }

      if ('realAdobe' in codes) {
        const mark = `${section.mark}-${codes.realAdobe}`
        const base = own(section.mark, mark)
        const name = `${codes.realAdobe}-${section.mark}-real-adobe.ncep`
        const renamed = rename(realAdobe, section.mark, mark)
        const pkg = writeProbe(out, name, base.entries, base.files, {
          [`CAD/${adobeName}`]: () => renamed,
        })
        reports.push(report(name, mark, section.family, 'real Adobe', pkg))
        expect(codesFor(pkg.issues, 'warning')).not.toContain('adobe-userpath')
      }

      if ('realPart' in codes) {
        const mark = `${section.mark}-${codes.realPart}`
        const base = own(section.mark, mark)
        const name = `${codes.realPart}-${section.mark}-real-part.ncep`
        const renamed = setPartRef(rename(realPart, section.mark, mark), partId(base.files))
        const pkg = writeProbe(out, name, base.entries, base.files, {
          [`CAD/${partName}`]: () => renamed,
        })
        reports.push(report(name, mark, section.family, 'real part', pkg))
      }

      if ('realBoth' in codes) {
        const mark = `${section.mark}-${codes.realBoth}`
        const base = own(section.mark, mark)
        const name = `${codes.realBoth}-${section.mark}-real-both.ncep`
        const renamedPart = setPartRef(rename(realPart, section.mark, mark), partId(base.files))
        const renamedAdobe = rename(realAdobe, section.mark, mark)
        const pkg = writeProbe(out, name, base.entries, base.files, {
          [`CAD/${partName}`]: () => renamedPart,
          [`CAD/${adobeName}`]: () => renamedAdobe,
        })
        reports.push(report(name, mark, section.family, 'real part + real Adobe', pkg))
      }

      if ('nested' in codes) {
        const mark = `${section.mark}-${codes.nested}`
        const base = own(section.mark, mark)
        const name = `${codes.nested}-${section.mark}-section-nested.ncep`
        const pkg = writeProbe(out, name, base.entries, base.files, {
          [`CAD/${partName}`]: nestSection,
        })
        reports.push(report(name, mark, section.family, 'section nested (negative)', pkg))
        expect(ncepErrors(pkg).length).toBeGreaterThan(0)
      }
    }

    expect(reports).toHaveLength(13)
    const header = [
      '| File | CadRoot Name | Family | Variant | Section paths | Adobe USERPATH | Parser |',
      '| --- | --- | --- | --- | --- | --- | --- |',
      ...reports.map(lineFor),
    ]
    const readme = [
      'Own NC → NCEP structure probes (700–712)',
      '',
      'Generated from test/fixtures/ncep/*.nc1 by the current converter. Every file is a complete',
      '.ncep package. Import one at a time in WiseCAM; the CadRoot Name is unique so WiseCAM does',
      'not reuse a cached part.',
      '',
      '## Test order',
      '1. Controls 700 / 706 / 709 / 711 / 712. If a control fails, stop and report it.',
      '2. U/I: test `adobe + real USERPATH` first (701 / 707 / 710), then `real Adobe`',
      '   (702 / 708), then `real part` (703) and `real part + real Adobe` (704).',
      '3. Tubes: controls 711 (SHS) and 712 (RHS).',
      '4. 705 is a negative control: the section group is nested inside cadpart. The parser must',
      '   reject it; if WiseCAM accepts it, our sibling-section rule is wrong.',
      '',
      '## What each variant isolates',
      '- control: our converter output.',
      '- adobe + real USERPATH: our part, our Adobe with USERPATH stripped, then the real U/I USERPATH group inserted. This is the old-writer failure mode.',
      '- real Adobe: our part + WiseCAM’s Adobe (includes USERPATH).',
      '- real part: WiseCAM’s part + our Adobe (with synthesized USERPATH).',
      '- real part + real Adobe: isolates the package docs/CadRoot from both SVGs.',
      '- section nested: known-bad structure; parser should error.',
      '',
      '## Matrix',
      ...header,
      '',
      'Parser pass is necessary but not sufficient. Record the actual WiseCAM result per file.',
      '',
    ].join('\n')
    writeFileSync(join(out, 'README.txt'), readme)

    const zipFiles: Record<string, Uint8Array> = {}
    for (const entry of reports) {
      zipFiles[entry.file] = new Uint8Array(readFileSync(join(out, entry.file)))
    }
    zipFiles['README.txt'] = strToU8(readme)
    const zipPath = `${out.replace(/\/+$/, '')}.zip`
    writeFileSync(zipPath, zipSync(zipFiles, { level: 6 }))
  }, 120_000)
})
